// build permutation of size s with c cycles and LDS=b
vector<int> buildD(int s,int b,int c){
    // special
    if(b==1){ vector<int> r(s); iota(r.begin(),r.end(),1); return r; } // identity, c must be s
    if(b==s){ // decreasing, c=ceil(s/2)
        vector<int> r(s); for(int i=0;i<s;i++) r[i]=s-i; return r;
    }
    int f=s-b;
    vector<int> sig(s);
    for(int i=0;i<f;i++) sig[i]=i+1;
    for(int i=f;i<s;i++) sig[i]=s-(i-f);
    // cmax = f + ceil(b/2)
    int cmax = f + (b+1)/2;
    int need = cmax - c; // number of transpositions
    // build swap list
    vector<pair<int,int>> sw;
    int up = (b+1)/2;
    for(int i=0;i<up;i++) sw.push_back({f+i, f+i+1});
    for(int i=f-1;i>=1;i--) sw.push_back({i, i+1});
    vector<int> pos(s+1); for(int i=0;i<s;i++) pos[sig[i]]=i;
    for(int t=0;t<need;t++){
        int u=sw[t].first, v=sw[t].second;
        swap(sig[pos[u]], sig[pos[v]]);
        swap(pos[u],pos[v]);
    }
    return sig;
}
int main(){
