int Tidal_Wave = 0;

int lisOf(const vector<int>&a){ // O(n log n)
    vector<int> d;
    for(int x:a){ auto it=lower_bound(d.begin(),d.end(),x); if(it==d.end())d.push_back(x); else *it=x; }
    return (int)d.size();
}
// permutation of size s with c cycles and LDS = b  (valid for 2<=b<=s-1, 1<=c<=s-b/2 ; specials handled outside)
vector<int> buildD(int s,int b,int c){
    if(b==1){ vector<int> r(s); iota(r.begin(),r.end(),1); return r; }
    if(b==s){ vector<int> r(s); for(int i=0;i<s;i++) r[i]=s-i; return r; }
    int f=s-b;
    vector<int> sig(s);
    for(int i=0;i<f;i++) sig[i]=i+1;
    for(int i=f;i<s;i++) sig[i]=s-(i-f);
    int cmax=f+(b+1)/2;
    int need=cmax-c;
    vector<pair<int,int>> sw;
    int up=(b+1)/2;
    for(int i=0;i<up;i++) sw.push_back({f+i,f+i+1});
    for(int i=f-1;i>=1;i--) sw.push_back({i,i+1});
    vector<int> pos(s+1); for(int i=0;i<s;i++) pos[sig[i]]=i;
    for(int t=0;t<need && t<(int)sw.size();t++){
        int u=sw[t].first,v=sw[t].second;
        swap(sig[pos[u]],sig[pos[v]]);
        swap(pos[u],pos[v]);
    }
    return sig;
}

int main(){
    int t; if(scanf("%d",&t)!=1)return 0;
    while(t--){
        int n,x,y,k; scanf("%d %d %d %d",&n,&x,&y,&k);
        bool ok=true;
        if(x<1||x>n||y<1||y>n||k<1||k>n) ok=false;
        else if(x==y){
            if(x==1||x==n){ ok=(k==n); }
        } else {
            int d=abs(x-y);
            int kmax=n-(d+1)/2;
            if((x==1&&y==n)||(x==n&&y==1)) ok=(k==kmax);
            else ok=(k<=kmax);
        }
        if(!ok){ printf("NO\n"); continue; }
        // construct (WLOG keep as is; if x>y swap at end)
        vector<int> P,Q; bool sw=false;
        if(x>y){ swap(x,y); sw=true; }
        if(x==y){
            if(x==1){ // decreasing
                P.resize(n); for(int i=0;i<n;i++)P[i]=n-i;
                Q=P;
            } else if(x==n){ P.resize(n); for(int i=0;i<n;i++)P[i]=i+1; Q=P; }
            else if(k==n){ // any perm with LIS x, use P_a form
                P.resize(n);
                for(int i=0;i<x-1;i++)P[i]=i+1;
                for(int i=x-1;i<n;i++)P[i]=n-(i-(x-1));
                Q=P;
            } else {
                // fallback: use buildD on whole? produce something (may be invalid)
                auto sig=buildD(n,x,k);
                P.resize(n); for(int i=0;i<n;i++)P[i]=n-i; // decreasing
                Q.resize(n); for(int i=0;i<n;i++)Q[i]=sig[P[i]-1];
            }
        } else if({x,y}==make_pair(1,n)){ // literal
            P.resize(n); for(int i=0;i<n;i++)P[i]=n-i;
            Q.resize(n); for(int i=0;i<n;i++)Q[i]=i+1;
        } else if(k>=x){
            int s0=n-(x-1);
            int b0=y-x+1;
            int c0=k-x+1;
            // tile permutation sigma on first s0 values? Use values 1..s0 for tile, then fixed points on s0+1..n
            // Actually place fixed points as the largest values, tile smallest.
            auto sig=buildD(s0,b0,c0);
            // P: tile decreasing, fixed increasing? additively increasing ranges
            P.clear(); Q.clear();
            // fixed points first (small values 1..x-1) then tile (large values)
            for(int v=1;v<=x-1;v++){ P.push_back(v); Q.push_back(v); }
            // tile values x..n, P decreasing
            for(int v=n;v>=x;v--) P.push_back(v);
            // tile Q = sigma(P_tile) with sigma on values x..n corresponding to 1..s0
            for(int v=n;v>=x;v--){ int idx=v-(x-1); Q.push_back(x-1+sig[idx-1]); }
        } else {
            // k<x : SC gadget + fixed points. Fallback attempt using P_a and buildD-complement search (small n only)
            // For safety produce a construction; may be invalid for large.
            int s0=n-k+1;
            int a0=x-k+1, b0=y-k+1;
            // try to find sigma single cycle with P_a: use buildD(s0,bb,1) for all bb, and complement, check
            vector<int> bestP,bestQ; bool found=false;
            auto makeQ=[&](const vector<int>&sig,const vector<int>&Pa){
                vector<int> Q(Pa.size()); for(size_t i=0;i<Pa.size();i++) Q[i]=sig[Pa[i]-1]; return Q;
            };
            auto PaOf=[&](int a,int s){ vector<int> r(s); for(int i=0;i<a-1;i++)r[i]=i+1; for(int i=a-1;i<s;i++)r[i]=s-(i-(a-1)); return r; };
            if(s0<=8){
                // brute all permutations
                vector<int> perm(s0); iota(perm.begin(),perm.end(),1);
                auto Pa=PaOf(a0,s0);
                do{
                    vector<char> vis(s0+1,0); int cyc=0;
                    for(int v=1;v<=s0;v++) if(!vis[v]){cyc++;int u=v;while(!vis[u]){vis[u]=1;u=perm[u-1];}}
                    if(cyc!=1) continue;
                    auto Q=makeQ(perm,Pa);
                    if(lisOf(Pa)==a0 && lisOf(Q)==b0){ bestP=Pa; bestQ=Q; found=true; break; }
                }while(next_permutation(perm.begin(),perm.end()));
            }
            if(!found){
                // heuristic: P_a with sigma=buildD(s0,b0,1) or complement
                auto Pa=PaOf(a0,s0);
                for(int bb=max(2,min(b0,s0-1)); bb<=min(b0,s0-1);bb++){
                    auto sig=buildD(s0,bb,1);
                    auto Q=makeQ(sig,Pa);
                    if(lisOf(Pa)==a0 && lisOf(Q)==b0){ bestP=Pa; bestQ=Q; found=true; break; }
                }
                if(!found){ // last resort P=Q=Pa
                    bestP=Pa; bestQ=Pa;
                }
            }
            // assemble: k-1 fixed points small values, then tile values
